window.t = function (key) {
    if (!TRANSLATIONS[currentLang] || !TRANSLATIONS[currentLang][key]) return key;
    return TRANSLATIONS[currentLang][key];
};

let currentLang = localStorage.getItem('app_lang') || 'en';

window.setLanguage = function (lang) {
    currentLang = lang;
    localStorage.setItem('app_lang', lang);

    // Update UI buttons
    document.querySelectorAll('.lang-btn').forEach(btn => {
        btn.classList.toggle('active', btn.id === `lang-${lang}`);
    });

    // Update text elements
    document.querySelectorAll('[data-i18n]').forEach(el => {
        const key = el.getAttribute('data-i18n');
        if (TRANSLATIONS[lang][key]) {
            el.innerText = TRANSLATIONS[lang][key];
        }
    });

    // Update placeholders
    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
        const key = el.getAttribute('data-i18n-placeholder');
        if (TRANSLATIONS[lang][key]) {
            el.placeholder = TRANSLATIONS[lang][key];
        }
    });

    // Re-render components that rely on language
    renderConcerts('all-events-list');
    if (currentUser) {
        renderProfile();
        updateHomeUserStatus();
        // Also re-render admin lists if in admin view
        const adminSec = document.getElementById('admin');
        if (adminSec && adminSec.classList.contains('active')) {
            renderAdminUsers();
            renderAdminBookings();
            renderAdminEvents();
        }
    }

    console.log(`Language set to: ${lang}`);
};

// ============================================================
// INIT
// ============================================================
document.addEventListener('DOMContentLoaded', () => {

    updateAdminStats();
    startClock();

    // Recover session
    const savedUser = localStorage.getItem('currentUser');
    if (savedUser) {
        currentUser = JSON.parse(savedUser);
        if (currentUser.id === 1) {
            currentUser.role = 'Developer';
            localStorage.setItem('currentUser', JSON.stringify(currentUser));
        }
        restoreLoginUI();
    }

    // Sync with Firebase (Replaces localStorage for global data)
    syncDataWithFirebase();

    // Load saved settings
    loadSavedAnnouncement();
    setLanguage(currentLang);
});

function syncDataWithFirebase() {
    // 1. Sync Concerts
    db.ref('concerts').on('value', (snapshot) => {
        const data = snapshot.val();
        if (data) {
            concerts = data;
            renderConcerts('all-events-list');
        } else {
            // If Firebase empty, push initial data
            db.ref('concerts').set(concerts);
        }
    });

    // 2. Sync Users
    db.ref('users').on('value', (snapshot) => {
        const data = snapshot.val();
        if (data) {
            // Ensure users is always a clean array without nulls
            users = (Array.isArray(data) ? data : Object.values(data)).filter(u => u !== null && u !== undefined);
            
            // Update current user if their role changed in DB
            if (currentUser) {
                const updatedMe = users.find(u => u.id == currentUser.id);
                if (updatedMe && updatedMe.role !== currentUser.role) {
                    currentUser.role = updatedMe.role;
                    localStorage.setItem('currentUser', JSON.stringify(currentUser));
                    restoreLoginUI();
                    updateHomeUserStatus();
                }
            }
        }
        renderAdminUsers();
    });

    // 3. Sync Bookings
    db.ref('bookings').on('value', (snapshot) => {
        const data = snapshot.val();
        // Just use empty array if Firebase is empty, don't push mock data back
        bookings = data ? (Array.isArray(data) ? data : Object.values(data)) : [];
        renderAdminBookings();
        updateAdminStats();
        if (currentUser) renderProfile();
    });

    // 4. Sync Site Status (Maintenance Mode)
    db.ref('siteStatus').on('value', (snapshot) => {
        const status = snapshot.val() || 'online';
        const body = document.body;
        const statusText = document.getElementById('site-status-text');
        const statusSelect = document.getElementById('admin-site-status');

        if (status === 'maintenance') {
            body.classList.add('maintenance-mode');
            if (statusText) {
                statusText.innerHTML = `● ${t('site_maintenance')}`;
                statusText.style.color = 'var(--pink-500)';
            }
        } else {
            body.classList.remove('maintenance-mode');
            if (statusText) {
                statusText.innerHTML = `● ${t('site_online')}`;
                statusText.style.color = '#10b981';
            }
        }
        if (statusSelect) statusSelect.value = status;
    });
}

// ============================================================
// NAVIGATION
// ============================================================
function showSection(id) {
    document.querySelectorAll('.section').forEach(s => s.classList.remove('active'));
    const sec = document.getElementById(id);
    if (sec) sec.classList.add('active');

    const main = document.getElementById('main-scroll');
    if (main) main.scrollTop = 0;

    if (id === 'profile') renderProfile();
    if (id === 'admin') { renderAdminBookings(); renderAdminEvents(); updateAdminStats(); }
    if (id === 'events') renderConcerts('all-events-list');
}

function switchBottomNav(id) {
    document.querySelectorAll('.bottom-nav-item').forEach(el => el.classList.remove('active'));
    const btn = document.getElementById('bnav-' + id);
    if (btn) btn.classList.add('active');
    showSection(id);
}

// ============================================================
// MODALS
// ============================================================
function openModal(id) {
    const m = document.getElementById(id + '-modal');
    if (m) {
        m.style.display = 'flex';
        setTimeout(() => m.classList.add('open'), 10);
        document.body.classList.add('modal-open');
    }
}

function closeModal(id) {
    const m = document.getElementById(id + '-modal');
    if (m) {
        m.classList.remove('open');
        setTimeout(() => {
            m.style.display = 'none';
            if (!document.querySelector('.modal.open')) {
                document.body.classList.remove('modal-open');
            }
        }, 300);
    }
}


function handleModalBgClick(e, id) {
    if (e.target === e.currentTarget) closeModal(id);
}

function switchModal(oldId, newId) {
    closeModal(oldId);
    setTimeout(() => openModal(newId), 350);
}

// ============================================================
// AUTH
// ============================================================
function handleLogin(e) {
    e.preventDefault();
    const nameId = document.getElementById('login-email').value.trim();

    // Users are already synced via syncDataWithFirebase()
    const user = users.find(u => u.name.toLowerCase() === nameId.toLowerCase());

    if (user) {
        if (user.banned) {
            showToast(t('toast_banned'));
            return;
        }
        currentUser = user;
        onLoginSuccess();
    } else {
        showToast(t('toast_login_fail'));
    }

    document.getElementById('login-email').value = '';
}

function onLoginSuccess() {
    closeModal('login');
    localStorage.setItem('currentUser', JSON.stringify(currentUser));
    restoreLoginUI();

    const highRoles = ["admin miru", "admin focus", "developer", "membership", "admin"];
    const currentRoleLower = (currentUser.role || '').toLowerCase();

    if (highRoles.some(r => currentRoleLower.includes(r))) {
        triggerGrandEntrance(currentUser);
    } else {
        showToast(`${t('toast_welcome')} ${currentUser.name}!`);
    }
    updateHomeUserStatus();

    // If admin logs in while in maintenance, bypass it
    const staffIds = [1, 2, 3];
    const isStaff = staffIds.includes(Number(currentUser.id)) || currentRoleLower.includes('admin') || currentRoleLower === 'developer';
    if (isStaff && document.body.classList.contains('maintenance-mode')) {
        document.body.classList.add('admin-view');
        showSection('admin');
    }
}


function restoreLoginUI() {
    if (!currentUser) return;

    const authBtns = document.getElementById('auth-buttons');
    if (authBtns) authBtns.style.display = 'none';

    const um = document.getElementById('user-menu');
    if (um) um.style.display = 'flex';

    const udn = document.getElementById('user-display-name');
    if (udn) udn.innerHTML = ''; // Removed from top nav to avoid crowding

    const av = document.getElementById('user-avatar');
    if (av) {
        if (currentUser.img) { av.src = currentUser.img; av.style.display = 'block'; }
        else { av.style.display = 'none'; }
    }

    showNavItem('bnav-profile');
    const roleLower = (currentUser.role || '').toLowerCase();

    // Permanent Staff IDs (Can access Admin menu regardless of role)
    const staffIds = [1, 2, 3];
    const isPermanentStaff = staffIds.includes(Number(currentUser.id));
    const isAdmin = isPermanentStaff || roleLower.includes('admin') || roleLower === 'developer';

    if (isAdmin) {
        showNavItem('bnav-admin');
        renderAdminEvents();
        renderAdminBookings();

        // Ensure admin-view is active if maintenance is on
        if (document.body.classList.contains('maintenance-mode')) {
            document.body.classList.add('admin-view');
        }
    }
    updateHomeUserStatus();
}

function updateHomeUserStatus() {
    const hus = document.getElementById('home-user-status');
    if (!hus) return;

    if (!currentUser) {
        hus.style.display = 'none';
        return;
    }

    hus.innerHTML = `
        <span style="font-weight:800; color:var(--pink-600); font-size:0.9rem;">${currentUser.name}</span>
        ${getRoleBadge(currentUser.role)}
    `;
    hus.style.display = 'flex';
}

function logout() {
    currentUser = null;
    localStorage.removeItem('currentUser');
    document.body.classList.remove('admin-view'); // Re-enable maintenance for anyone who logs out

    document.getElementById('auth-buttons').style.display = 'flex';
    document.getElementById('user-menu').style.display = 'none';
    hideNavItem('bnav-profile');
    hideNavItem('bnav-admin');
    switchBottomNav('home');

    const hus = document.getElementById('home-user-status');
    if (hus) hus.style.display = 'none';

    showToast(t('toast_logout'));

    // If maintenance is on, go back to home to see overlay
    if (document.body.classList.contains('maintenance-mode')) {
        location.reload();
    }
}

function handleRegister(e) {
    e.preventDefault();
    const name = document.getElementById('reg-name').value.trim();

    if (users.find(u => u.name.toLowerCase() === name.toLowerCase())) {
        showToast(t('toast_reg_fail'));
        return;
    }

    const newUser = {
        id: Date.now(),
        name: name,
        role: 'user'
    };
    users.push(newUser);

    // Sync with Firebase
    db.ref('users').set(users)
        .then(() => {
            showToast(t('toast_reg_success'));
            switchModal('register', 'login');
        })
        .catch(err => {
            alert("Firebase Save Error: " + err.message + "\n(Please check your Firebase Database Rules!)");
            console.error(err);
        });
}

function handleLineLogin() {
    const btn = document.querySelector('.btn-line');
    if (btn) { btn.disabled = true; btn.style.opacity = '0.6'; }

    showToast('🔄 กำลังเชื่อมต่อ LINE...');

    // Re-enable button after 5 seconds in case something goes wrong
    setTimeout(() => {
        if (btn) { btn.disabled = false; btn.style.opacity = '1'; }
    }, 5000);

    try {
        if (liff.isLoggedIn()) {
            // Already logged in — get profile directly
            liff.getProfile().then(profile => {
                handleLiffUser(profile);
            }).catch(err => {
                console.error('LIFF Profile Error:', err);
                showToast('❌ ไม่สามารถดึงข้อมูล LINE ได้');
                if (btn) { btn.disabled = false; btn.style.opacity = '1'; }
            });
        } else {
            // Not logged in — redirect to LINE OAuth
            // Page will reload after auth, initLIFF() will auto-login
            liff.login();
        }
    } catch (err) {
        console.error('LINE Login Error:', err);
        showToast('❌ LINE Error: ' + (err.message || 'กรุณาลองใหม่'));
        if (btn) { btn.disabled = false; btn.style.opacity = '1'; }
    }
}

