function renderConcerts(listId) {
    const list = document.getElementById(listId);
    if (!list) return;
    list.innerHTML = '';

    // Filter logic: Home list only shows recommended, All list shows everything
    const filteredConcerts = concerts;

    if (filteredConcerts.length === 0) {
        list.innerHTML = `<div class="empty-state" style="grid-column:1/-1;"><p>${t('empty_no_concert')}</p></div>`;
        return;
    }

    // Apply consistent artistic layout (Symmetric Tilt) to all concert grids
    list.classList.add('stacked');

    filteredConcerts.forEach(c => {
        const card = document.createElement('div');
        card.className = 'concert-card';

        let statusBadge = '';
        if (c.status === 'open') statusBadge = `<div class="badge-status open">${t('badge_open')}</div>`;
        else if (c.status === 'coming') statusBadge = `<div class="badge-status coming">${t('badge_coming')}</div>`;

        const displayPrice = typeof c.price === 'string' && c.price.includes('/')
            ? `${t('card_start_price')}${c.price.split('/')[0].trim()}`
            : `${t('card_start_price')}${typeof c.price === 'number' ? c.price.toLocaleString() : c.price}`;

        card.innerHTML = `
            <div class="concert-img-wrap">
                <img src="${c.img}" class="concert-img" alt="${c.title}">
                ${statusBadge}
            </div>
            <div class="concert-info">
                <div class="concert-title">${c.title}</div>
                <div class="concert-meta">
                    <i class="fas fa-calendar"></i> ${c.date}<br>
                    <i class="fas fa-map-marker-alt"></i> ${c.venue}<br>
                    <i class="fas fa-ticket-alt" style="color:var(--pink-500)"></i> ${t('card_quantity')}: ${c.quantity} ${t('card_tickets')}
                </div>
                <div class="concert-footer" style="justify-content: flex-end;">
                    <button class="btn-primary btn-card" onclick="startBooking(${c.id})"><i class="fas fa-ticket-alt"></i> ${t('card_book_now')}</button>
                </div>
            </div>
        `;
        list.appendChild(card);
    });
}

function formatThaiDate(val) {
    if (!val) return '';
    const days = ['อาทิตย์', 'จันทร์', 'อังคาร', 'พุธ', 'พฤหัสบดี', 'ศุกร์', 'เสาร์'];
    const months = [
        'มกราคม', 'กุมภาพันธ์', 'มีนาคม', 'เมษายน', 'พฤษภาคม', 'มิถุนายน',
        'กรกฎาคม', 'สิงหาคม', 'กันยายน', 'ตุลาคม', 'พฤศจิกายน', 'ธันวาคม'
    ];
    const d = new Date(val);
    if (isNaN(d.getTime())) return '';
    const dayName = days[d.getDay()];
    const dateNum = d.getDate();
    const monthName = months[d.getMonth()];
    const yearBE = d.getFullYear() + 543;
    return `วัน${dayName}ที่ ${dateNum} ${monthName} ${yearBE}`;
}

window.updateThaiDateDisplay = function (val) {
    const displayWrap = document.getElementById('booking-date-thai');
    const displayText = document.getElementById('thai-date-text');
    if (!val || !displayWrap || !displayText) {
        if (displayWrap) displayWrap.style.display = 'none';
        return;
    }
    const formatted = formatThaiDate(val);
    if (formatted) {
        displayText.innerText = formatted;
        displayWrap.style.display = 'flex';
    } else {
        displayWrap.style.display = 'none';
    }
};

